package rules

// Описания и истории рас и классов. Тексты общие для настольного мира D&D и годятся для любой кампании;
// мастер волен переписать историю под свой мир.
type text struct{ Desc, Lore string }

var raceText = map[string]text{
	"aarakocra": {"Птицелюды с яркими перьями и острыми когтями. Живут на горных пиках и в небе, ценят свободу превыше всего.",
		"Ааракокра селятся в гнёздах на отвесных скалах, куда не добраться пешему. Их предания говорят, что первые из них были птицами, которым ветер подарил разум. Мир внизу они считают шумным и тесным, но их вожаки отправляют отважных разведчиков к другим народам — выменивать металл и новости. Тех, кто навсегда спускается на землю, называют «потерявшими крылья ветра», хотя многие становятся лучшими следопытами и вестниками."},
	"aasimar": {"Потомки людей, отмеченные небесным светом. Их лица красивы, глаза порой светятся, а в сердце живёт зов высшего долга.",
		"Аасимары рождаются у смертных, в чьём роду когда-то оказалась кровь небожителей — или по прямому благословению божества. Иногда ребёнок с сияющими глазами появляется в семье, никогда не знавшей чудес. Одни аасимары чувствуют зов защищать слабых, другие несут свет как кару для зла, а третьи сбиваются с пути, и тьма искажает их дар. Для многих это бремя: они знают, что рождены для большего, но не всегда знают для чего."},
	"bugbear": {"Рослые мохнатые гоблиноиды с длинными руками. Бесшумны, терпеливы и страшны в засаде.",
		"Багбиры считают себя охотниками и разбойниками, а не воинами. Их племена поклоняются Хруггеку, богу засад, и учат детей прятаться в тенях, пока добыча не подойдёт на расстояние удара. Среди других народов их ценят как наёмников и разведчиков, но боятся: багбир никогда не атакует, пока не уверен в победе. Те, кто выбрал жизнь среди других рас, обычно бегут от жестоких вождей."},
	"dragonborn": {"Гордые рептилоидные воины с драконьей кровью. Чешуя, когти и дыхание стихии делают их грозными бойцами.",
		"Драконорождённые вышли из яиц, отложенных по воле драконов-богов или созданных в давних экспериментах. Их общество построено вокруг кланов и чести: проигрыш в споре, трусость или предательство клана — худший позор. Каждый носит имя клана впереди собственного. Они не любят магию, не освящённую долгом, и всегда помнят первую клятву: оправдать кровь предков. Дыхание дракона — вершина их гордости и последний довод в споре."},
	"dwarf": {"Коренастые бородатые мастера гор. Выносливы, упрямы, чтят клан, ремесло и данное слово.",
		"Дварфы выкопали свои города в корнях гор, когда мир был молод. Их кузни выковали лучшие клинки и самые прочные стены, а у каждой семьи есть пивоварня и древний счёт обид. Дварфы помнят каждую обиду и каждую услугу многие века. Холмовые славятся мудростью и здоровьем, горные — силой и мастерством в броне. Золото они ценят, но честь и слово в их мире стоят дороже любых сундуков."},
	"elf": {"Грациозные долгоживущие дети леса и древней магии. Тонкие чувства, лёгкая походка и вечная печаль по ушедшему.",
		"Эльфы пришли в мир ещё до королевств людей и помнят события, которые остальные считают легендами. Высшие эльфы строят башни и изучают магию, лесные живут в тихих чащах, а тёмные эльфы дроу, изгнанные в подземья, стали народом интриг и паутины. Эльфы не спят, а входят в транс и в нём видят воспоминания. Время для них течёт иначе: клятва, данная эльфом, может исполняться столетиями."},
	"firbolg": {"Великаны-мирные хранители леса, рослые, с синеватой кожей. Предпочитают прятаться от мира, но защищают природу яростно.",
		"Фирболги — потомки великанов, которых лес научил смирению. Они живут в глухих чащах кланами, говорят с духами природы и всегда ищут равновесия. Чужаков встречают осторожно: многие из них были охотниками на великанов и вырубали леса. Когда лес в беде, фирболги выходят из тени — молчаливые, огромные и неумолимые. Они ценят подарки, особенно мёд и тихие песни."},
	"genasi": {"Дети стихий: потомки джиннов, ифритов, дао и маридов. Кожа, волосы и глаза выдают стихию, текущую в крови.",
		"Дженази появляются, когда в роду смертных оказалась кровь существ стихий. Воздушные лёгки и непостоянны, земляные медлительны и упрямы, огненные вспыльчивы и ярки, водные холодны и загадочны. Дженази нередко считают чужаками среди людей и ищут своё место: одни уходят к стихийным храмам, другие становятся странствующими искателями приключений. Их тела верны своей стихии даже после смерти: огненные дженази оставляют пепел, водные — лужицу воды."},
	"gnome": {"Маленькие изобретатели и шутники. Любопытны, остроумны и обожают тайны, механизмы и иллюзии.",
		"Гномы жили в холмах и лесах, ещё когда мир был моложе, и до сих пор считают любопытство высшей добродетелью. Лесные гномы дружат со зверьми и прячутся в чащах; скальные строят часовые механизмы, взрывающиеся фейерверки и безумные летательные аппараты. Гномья жизнь долгая: многие тратят её на одно большое изобретение. Взрывы в мастерской считаются у них чем-то вроде сбывшейся шутки."},
	"goblin": {"Маленькие хитрые гоблиноиды. Быстры, изобретательны и по необходимости научились выживать в мире больших и злых.",
		"Гоблины веками жили под гнётом хобгоблинов и багбиров и научились ценить хитрость выше силы. Племя гоблинов — это норы, ловушки и острые языки. Но среди них встречаются те, кто ушёл из племени ради мира людей: вор, механик, разведчик. Гоблины быстро учатся и ещё быстрее убегают, когда дело оборачивается плохо."},
	"goliath": {"Рослые горные силачи с серой кожей. Верят, что всё в жизни — состязание, а честь — в выносливости.",
		"Голиафы живут на вершинах, куда ветер забрасывает облака. В их племенах нет слабых: каждого учат состязаться с детства, а победа измеряется не только в силе, но и в том, как ты помогаешь племени. Голиаф, пережив падение, считает это уроком гор. Имена они получают за дела: «Тот-Кто-Не-Отступил», «Камень-Над-Пропастью». Те, кто спускается вниз, часто становятся наёмниками, и для них это не работа, а проверка."},
	"halfelf": {"Дитя двух миров: людей и эльфов. Харизматичны, быстро приспосабливаются и нигде не чувствуют себя до конца дома.",
		"Полуэльфы — наследники редких союзов людей и эльфов. От людей им досталась жажда жизни, от эльфов — грация и острый слух. Они долго живут и быстро теряют тех, кого любят, и это делает их внимательными и осторожными в привязанностях. Полуэльфы нередко становятся дипломатами, бардами и странниками, ведь они понимают оба мира и принадлежат им обоим наполовину."},
	"halforc": {"Могучие потомки людей и орков. Суровый облик скрывает стремление доказать, что сила не равна жестокости.",
		"Полуорки рождаются, когда орочьи орды встречаются с людьми, — иногда в войне, иногда в мире. Среди орков их принимают за слабых, среди людей — за диких. Многие всю жизнь доказывают обратное: становятся защитниками, героями и вождями. Свирепость в бою у них в крови, но гнев можно направить: полуорки, выбравшие путь чести, оказываются самыми верными друзьями."},
	"halfling": {"Невысокие, добродушные и удивительно удачливые любители уюта. Любят друзей, еду и мирные деревни.",
		"Полурослики веками жили на холмах и в речных долинах, не стремясь к власти, пока остальной мир воевал. Их сила — в семье, пироге и маленькой удаче, которая выручает в безвыходных ситуациях. Легконогие бродят по дорогам и умеют исчезать на открытом месте, коренастые крепки как дубовые бочки. Когда приходит беда, полурослики оказываются храбрее, чем кто-либо ожидал."},
	"hobgoblin": {"Дисциплинированные воины-гоблиноиды. Живут по уставу, чтут иерархию и ненавидят беспорядок.",
		"Хобгоблины создали армии, где каждый знает место и обязанности. Их легионы — это строй, обучение и железная выучка, а честь измеряется верностью приказу. Те, кто ушёл из легиона, часто ищут новое дело: наёмничество, стражу или искусство войны. Хобгоблин, потерпевший поражение, мучительно переживает стыд, и «спасти лицо» для него — вопрос жизни."},
	"human": {"Самый многочисленный и разнообразный народ. Живут недолго, зато стремятся многое успеть.",
		"Люди коротко живут, поэтому торопятся — и потому построили империи, города и тысячи религий за малое время. Нет земли, где бы не было человеческой деревни, и нет занятия, в котором не нашлось бы человека-мастера. У людей нет единой судьбы: каждый пишет её сам. Их адаптивность — главный дар, а амбиции — главная опасность."},
	"kenku": {"Бескрылые птицеподобные существа, лишённые дара собственной речи. Говорят чужими голосами и звуками.",
		"Давно, по легенде, кенку были крылатыми слугами тёмного хозяина, но обманули его и были прокляты: потеряли крылья и собственный голос. Теперь кенку подражают звукам, слышанным когда-либо. Они мастера подделок, воры и шпионы по необходимости, а не по природе. Их мечта — вернуть крылья, а пока — вынести чужую речь на сцену жизни, склеив фразы из услышанного."},
	"kobold": {"Мелкие чешуйчатые существа, преданные драконам. Хитры, суетливы и опасны стаей.",
		"Кобольды поклоняются драконам как богам и воспринимают себя кровными родичами. Живут в туннелях и пещерах, строят ловушки больше, чем оружие, и побеждают умом и числом. Авантюристы-кобольды обычно беглецы из племён или те, кто хочет доказать, что маленький не значит слабый. Они трудолюбивы, верны и невероятно изобретательны, когда речь о ловушках."},
	"lizardfolk": {"Хладнокровные болотные охотники с чешуёй и хвостом. Мыслят практично и не знают жалости к слабым.",
		"Ящеролюды выживают в болотах и лагунах, где слабый не доживает до рассвета. Они логичны и холодны: эмоции кажутся им странной слабостью других народов. Но верность племени и охота священны. Ящеролюд-путешественник присматривается к чужим обычаям как биолог: иногда подражая, иногда не понимая, но всегда выживая."},
	"minotaur": {"Рогатые великаны с головой быка. Неудержимы в натиске и преданы клану.",
		"Минотавры из древних лабиринтов и островов. Их предания хранят память о проклятии, сделавшем одних владыками каменных коридоров, других — изгоями. Минотавры чтят честь, силу и верность клану, а гнев их подобен лавине. Тот, кто идёт по миру минотавром-искателем, ищет не битвы, а смысл: что делать с силой, которую не можешь отпустить."},
	"orc": {"Свирепые воины орочьих орд. Сильны, выносливы и подчиняются зову крови и богов войны.",
		"Орки — дети Груумша Одноглазого, бога войны, и их истории — это сказания о набегах и победах. Орда ценит силу вождя и свободу кочевья. Но не все орки живут войной: некоторые находят в себе иную силу — мастерство, веру, дружбу. Орк-искатель приключений часто тот, кого орда изгнала, или тот, кто устал от кровопролития ради крови."},
	"tabaxi": {"Кошколюди-странники, любопытные и ловкие. Охотятся за историями, диковинками и необычными вещами.",
		"Табакси — кочевники и искатели, которых ведёт любопытство. Каждый из них стремится собрать коллекцию — историй, артефактов, воспоминаний. В их культуре «преследование» — священный ритуал, и у каждого есть собственная одержимость. Они быстры, как кошки, и непостоянны в привязанностях, но свято хранят тех, кто разделил с ними приключение."},
	"tiefling": {"Потомки людей, отмеченные инфернальной кровью. Рога, хвост и необычные глаза обрекают на недоверие.",
		"Давний договор предков с исчадиями Преисподней оставил на тифлингах печать: рога, хвосты, необычный цвет кожи и глаз. За грехи предков им приходится расплачиваться подозрительностью людей. Многие из них становятся мастерами скрытности и дипломатии, чтобы выжить, другие намеренно вызывают страх. Но кровь не определяет судьбу: тифлинг может быть и героем, и злодеем — как любой другой."},
	"tortle": {"Черепахоподобные странники в прочных панцирях. Мирные, философские и очень выносливые.",
		"Тортлы живут на побережьях и в дельтах рек, где стали мудрыми странниками. Панцирь — их дом, и, по обычаю, тортл всегда носит его с собой. Они не любят спешку, ценят покой и считают, что мир лучше всего познаётся шагом. Но когда нужно, они стоят насмерть: спрятавшись в панцирь, тортл становится непробиваемой крепостью."},
	"triton": {"Морские жители, посланцы глубин, защитники океана. Горды и уверены в своей миссии.",
		"Тритоны хранят подводные города и охраняют границы морских глубин от кракенов, дьяволов и иной нечисти. Многие столетия они не вмешивались в дела суши, но теперь поднимаются, чтобы предупредить: зло глубже, чем кажется. Они высокомерны к «малым народам суши», но справедливы и бесстрашны. Тритон на суше — это дипломат и воин одновременно."},
	"warforged": {"Живые конструкты из металла, дерева и магии. Созданы для войны, но ищут собственную цель.",
		"Воплощённых создавали для великой войны как солдат и наёмников. Когда война закончилась, они оказались без цели. Их тела не стареют и не нуждаются в сне, но разум полон вопросов: есть ли у них душа, что значит быть свободным, чего они хотят. Одни остаются верны старым приказам, другие находят новую цель в странствиях и дружбе."},
	"yuanti": {"Змеиные люди с кожей, местами покрытой чешуёй. Хитры, амбициозны, невосприимчивы к ядам.",
		"Юань-ти чистокровные — самые похожие на людей из змеиного народа. Они вплетаются в человеческое общество, скрывая природу, и служат тайным целям культов змеиного бога. Их кровь неподвластна яду, а голос убеждает. Те, кто покинул своё гнездо, ищут убежища в мире людей или пытаются отвернуться от наследия змей."},
}

var classText = map[string]text{
	"barbarian": {"Неистовый воин, чья сила питается яростью. В гневе не чувствует боли и крушит всё на пути.",
		"Варвары приходят из племён, где выживание зависит от силы и духа предков. Для одних ярость — священный дар тотема, для других — проклятие, которое надо держать на привязи. Варвар не знает тактики дворов и армий, зато знает, как стоять насмерть. Многие уходят от своих племён на поиски славы, мести или искупления."},
	"bard": {"Музыкант, рассказчик и маг слова. Вдохновляет союзников, очаровывает врагов и знает понемногу обо всём.",
		"Барды хранят память мира: песни, предания, тайные ритуалы. Их ремесло уходит в времена, когда магия и музыка были одним искусством, а слово могло строить города. Коллегии бардов учат истории, ритуалам и интриге. Бард редко сражается в первой линии, но без него команда не слышит себя."},
	"cleric": {"Служитель божества, наделённый божественной силой. Лечит, защищает и карает врагов веры.",
		"Жрецы получают силу от богов, но не слепо: каждый выбирает домен, определяющий образ служения. Жрец жизни исцеляет и хранит, жрец войны ведёт армии, жрец знаний ищет истину. Их вера проверяется сомнениями, и часто сильнейший жрец — тот, кто потерял бога и всё равно продолжил служить."},
	"druid": {"Хранитель природы и лесов. Владеет магией стихий и принимает облик зверей.",
		"Друиды ведут свой род от тех, кто первыми заметил, что мир живой. Они не подчиняются королям и храмам, только равновесию. Друид-странник защищает рощи, друид-отшельник живёт один среди зверей. Превращаясь, друид не притворяется зверем, а вспоминает, что и он — часть дикой природы."},
	"fighter": {"Мастер оружия и тактики. Закалён тренировками и войнами, умеет всё, что связано с боем.",
		"Воины — самые разнообразные искатели приключений: рыцари, наёмники, гладиаторы, ветераны. У каждого свой путь, но все знают цену дисциплины. Воин не нуждается в магии: сталь, выучка и характер — его арсенал. Чемпион доводит точность до совершенства, а другие архетипы открывают иные стили боя."},
	"monk": {"Воин духа и тела, отточивший тело до оружия. Использует ки — внутреннюю энергию.",
		"Монахи тренируются в монастырях на вершинах гор и в тихих долинах. Они ищут единство тела и духа, а их удары быстры и точны. Монах не носит доспехов — его броня в скорости и концентрации. Традиция открытой ладони учит, что лучшее оружие — контроль над врагом."},
	"paladin": {"Священный воин, давший клятву. Объединяет мощь меча и силу божественного благословения.",
		"Паладин приносит клятву: защищать, мстить, хранить древние законы. Клятва становится его хребтом и приговором: нарушенное слово лишает силы. Паладины ведут войска, охраняют святыни и приходят на помощь слабым. Для многих клятва — единственное, что отделяет их от пустоты."},
	"ranger": {"Следопыт и охотник дикой местности. Знает врагов, тропы и тайны природы.",
		"Следопыты стерегут границы цивилизации: выслеживают чудовищ, проводят караваны через чащи, предупреждают о набегах. Они живут вдали от городов и знают звериные тропы лучше человеческих улиц. Охотник учится драться со многими или с гигантами, а природа даёт ему тихую магию."},
	"rogue": {"Мастер скрытности и ловкости. Находит слабое место и бьёт без предупреждения.",
		"Плуты — воры, шпионы, разведчики, дуэлянты. Ремесло требует хитрости и холодной головы: один неверный шаг в замке или в темноте — и ты мёртв. Плут редко выигрывает в лобовой схватке, зато оказывается там, где его не ждут. Вор ловок руками, как никто, и знает цену любому замку."},
	"sorcerer": {"Маг, чья сила рождена в крови. Колдует инстинктивно, без книг и учителей.",
		"Магия чародея — дар, а не наука: наследие драконов, отметка дикой магии, влияние иного мира. Он рождается с силой, которую сам не понимает, и учится её сдерживать. Чародеи кажутся людям опасными: заклинание может сорваться в минуту гнева. Драконья кровь придаёт силу и стойкость, а волю нужно воспитывать годами."},
	"warlock": {"Колдун, заключивший договор с могущественным покровителем. Магия приходит как плата и как цепь.",
		"Колдуны заключают сделки с исчадиями, феями, древними сущностями. Покровитель даёт силу, а взамен требует услуг, душ или просто интереса к судьбе колдуна. Магия колдуна проще, чем у волшебника, но сильнее и опаснее: она не восстанавливается по расписанию, а дарится по милости покровителя."},
	"wizard": {"Учёный-маг, постигающий силу тайных знаний. Заклинания записаны в книге и добыты многолетним трудом.",
		"Волшебник изучает магию как науку: школы, формулы, ритуалы. Его книга заклинаний ценнее золота, а библиотека — второй дом. Эвокатор оттачивает разрушительные заклинания, и каждый его огненный шар точен. Волшебники часто слабы телом, зато каждый враг опасается их знаний."},
	"artificer": {"Изобретатель, соединяющий магию и механику. Создаёт и улучшает предметы, чинит союзников и строит чудеса.",
		"Изобретатели считают магию инженерным делом. Одни работают в мастерских при королях, другие скитаются по миру со своими устройствами. Их заклинания — это чертежи, воплощённые в железе: жезл, механический зверь, зелье. Алхимик среди них варит эликсиры, исцеляющие и калечащие. Изобретатель редко первым идёт в бой, но без него команда остаётся без инструментов."},
	"bloodhunter": {"Охотник на нечисть, платящий кровью за силу. Жертвует частью себя, чтобы побеждать монстров.",
		"Охотники на кровь — одиночки или члены тайных орденов, видевшие, что творят чудовища. Ритуалы наделяют их силой за плату: болью, кровью и риском. Они выслеживают оборотней, вампиров, нежить. Орден призраков учит бороться с духами. Общество их боится не меньше чудовищ, а они продолжают охоту, потому что иначе нельзя."},
}

// Catalog применяет тексты к расам и классам (включая подрасы без собственного текста).
func withText(rs []Race) []Race {
	out := make([]Race, len(rs))
	for i, r := range rs {
		t := raceText[r.ID]
		r.Desc, r.Lore = t.Desc, t.Lore
		out[i] = r
	}
	return out
}

func withClassText(cs []Class) []Class {
	out := make([]Class, len(cs))
	for i, c := range cs {
		t := classText[c.ID]
		c.Desc, c.Lore = t.Desc, t.Lore
		out[i] = c
	}
	return out
}
